<?php
namespace App\Http\Controllers;use App\Models\{Employee,Company,Project,Designation};use Illuminate\Http\Request;class EmployeeController extends Controller{function index(Request $r){$items=Employee::with('company','designation','currentProject')->when($r->search,fn($q,$v)=>$q->where('name','like',"%$v%")->orWhere('iqama_no','like',"%$v%"))->latest()->paginate(25);return view('employees.index',compact('items'));}function create(){return view('employees.form',$this->data(new Employee));}function store(Request $r){Employee::create($this->valid($r));return redirect()->route('employees.index')->with('success','Employee saved');}function show(Employee $employee){$employee->load('company','designation','currentProject','attendanceRecords','advancePayments','extraDuties','payslips');return view('employees.show',compact('employee'));}function edit(Employee $employee){return view('employees.form',$this->data($employee));}function update(Request $r,Employee $employee){$employee->update($this->valid($r));return redirect()->route('employees.show',$employee)->with('success','Employee updated');}function destroy(Employee $employee){$employee->delete();return back()->with('success','Deleted');}function valid($r){return $r->validate(['name'=>'required','employee_code'=>'nullable','iqama_no'=>'nullable','passport_no'=>'nullable','designation_id'=>'nullable|exists:designations,id','company_id'=>'nullable|exists:companies,id','current_project_id'=>'nullable|exists:projects,id','shift'=>'nullable','accommodation'=>'nullable','doj'=>'nullable|date','phone'=>'nullable','hourly_rate'=>'nullable|numeric','monthly_salary'=>'nullable|numeric','status'=>'nullable','remarks'=>'nullable']);}function data($employee){return ['employee'=>$employee,'companies'=>Company::orderBy('name')->get(),'projects'=>Project::orderBy('name')->get(),'designations'=>Designation::orderBy('name')->get()];}}
